    listFormats: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description The matrix. */
            200: {
                headers: {
                    "X-Request-Id"?: string;
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "sources": [
                     *         {
                     *           "extension": ".docx",
                     *           "mediaType": "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
                     *           "family": "writer",
                     *           "targets": [
                     *             "pdf",
                     *             "odt",
                     *             "txt",
                     *             "html",
                     *             "rtf",
                     *             "epub"
                     *           ]
                     *         }
                     *       ],
                     *       "targets": [
                     *         {
                     *           "id": "pdf",
                     *           "extension": ".pdf",
                     *           "mediaType": "application/pdf",
                     *           "label": "PDF",
                     *           "multiple": false
                     *         },
                     *         {
                     *           "id": "png",
                     *           "extension": ".png",
                     *           "mediaType": "image/png",
                     *           "label": "PNG",
                     *           "multiple": true
                     *         }
                     *       ]
                     *     }
                     */
                    "application/json": {
                        /** @description Accepted upload types, keyed by extension. */
                        sources: {
                            /** @example .docx */
                            extension: string;
                            mediaType: string;
                            /**
                             * @description The LibreOffice document family that handles it.
                             *     Sources in the same family convert the same way.
                             *
                             *     `null` for a source LibreOffice does not open at
                             *     all - `.psd` today. Such a source is handled
                             *     entirely by this service's own code, which is why
                             *     it can only ever offer `extract` targets; its
                             *     absence is a fact about the source rather than a
                             *     field this version happens to omit.
                             * @enum {string|null}
                             */
                            family: "writer" | "calc" | "impress" | "draw" | null;
                            targets: components["schemas"]["TargetId"][];
                        }[];
                        /** @description Every format this service can produce. */
                        targets: {
                            id: components["schemas"]["TargetId"];
                            /** @example .pdf */
                            extension: string;
                            mediaType: string;
                            /**
                             * @description Short name, as used in error messages.
                             * @example PDF
                             */
                            label: string;
                            /**
                             * @description When true the response is a ZIP of one file per page
                             *     rather than a single file. Always an archive for
                             *     these, even for a one-page source.
                             */
                            multiple: boolean;
                        }[];
                    };
                };
            };
        };
    };
